<?php
require '../config/db.php';require '../config/auth.php';require_role('admin','login.php');
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="smart-parish-appointments-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Reference','Parishioner','Email','Service','Date','Start','End','Resource','Status']);$q=$pdo->query("SELECT a.reference_no,u.full_name,u.email,s.name service,a.appointment_date,a.start_time,a.end_time,r.name resource,a.status FROM appointments a JOIN users u ON u.id=a.user_id JOIN services s ON s.id=a.service_id LEFT JOIN resources r ON r.id=a.resource_id ORDER BY a.appointment_date DESC");foreach($q as $r)fputcsv($out,[$r['reference_no'],$r['full_name'],$r['email'],$r['service'],$r['appointment_date'],$r['start_time'],$r['end_time'],$r['resource'],$r['status']]);fclose($out);exit;}
$monthly=$pdo->query("SELECT DATE_FORMAT(appointment_date,'%Y-%m') month,COUNT(*) total,SUM(status='completed') completed,SUM(status='cancelled') cancelled FROM appointments GROUP BY DATE_FORMAT(appointment_date,'%Y-%m') ORDER BY month DESC LIMIT 12")->fetchAll();$popular=$pdo->query("SELECT s.name,COUNT(a.id) total FROM services s LEFT JOIN appointments a ON a.service_id=s.id GROUP BY s.id ORDER BY total DESC")->fetchAll();$statusRows=$pdo->query('SELECT status,COUNT(*) total FROM appointments GROUP BY status')->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><button class="btn light mobile-toggle" data-nav-toggle>☰</button><div class="eyebrow">Analytics</div><h1>Reports.</h1></div><div class="actions"><a class="btn" href="?export=csv">Export CSV</a><button class="btn light" onclick="window.print()">Print / PDF</button></div></header><section class="grid three"><?php foreach($statusRows as $r):?><div class="card stat"><span class="muted"><?=e(ucfirst($r['status']))?></span><strong><?=$r['total']?></strong></div><?php endforeach?></section><br><section class="grid two"><div class="card table-wrap"><h2>Monthly appointments</h2><table class="table"><thead><tr><th>Month</th><th>Total</th><th>Completed</th><th>Cancelled</th></tr></thead><tbody><?php foreach($monthly as $r):?><tr><td><?=e($r['month'])?></td><td><?=$r['total']?></td><td><?=$r['completed']?></td><td><?=$r['cancelled']?></td></tr><?php endforeach?></tbody></table></div><div class="card"><h2>Services by demand</h2><?php foreach($popular as $r):?><p><b><?=e($r['name'])?></b><br><span class="muted"><?=$r['total']?> appointment(s)</span></p><?php endforeach?></div></section></main></div><script src="../assets/js/script.js"></script></body></html>
